"""catalog.py, the reference data's names a proposal's item must come from: generated by generate_catalog.py from
db/reference, the clinic's common catalog items and the common names in db/reference/dictation-names.toml, and kept up
to date with them; and among the checks, so a change to it asks for the stored answers to be scored again, never for a
new eval run. Each common name stands for items the reference data holds as its kind, is an item of that kind only,
and is never a negation, a number word or a word of the closed sentence's classes."""

from __future__ import annotations

import sys
import tomllib
from pathlib import Path

import pytest

from ehr_dictation import provenance, validation
from ehr_dictation.textnorm import STOPWORDS

SIDECAR = Path(__file__).resolve().parents[1]
REPOSITORY = SIDECAR.parents[2]
sys.path.insert(0, str(SIDECAR))
import generate_catalog  # noqa: E402


def test_the_catalog_is_up_to_date_with_the_reference_data():
    committed = (SIDECAR / "ehr_dictation" / "catalog.py").read_text(encoding="utf-8")

    assert committed == generate_catalog.render(), (
        "ehr_dictation/catalog.py is out of date: uv run --project src/Ehr.Dictation/sidecar python "
        "src/Ehr.Dictation/sidecar/generate_catalog.py"
    )


def test_the_catalog_is_one_of_the_checks_not_the_pipeline():
    assert "catalog.py" in provenance.CHECKS
    assert provenance.PIPELINE_CODE_SHA256 == provenance.code_sha256(
        names=[path.name for path in provenance.PACKAGE.glob("*.py")
               if path.name not in {"validation.py", "textnorm.py", "catalog.py", "api.py", "provenance.py"}]
    )


def test_each_source_gives_names():
    orderables, allergens, counts = generate_catalog.names()

    assert all(counts.values())
    assert {"+^lisinopril$ mg oral tablet", "+^amoxicillin$", "^complete blood count$ ^cbc$", "^screening mammogram$",
            "^chest x ray$ views"} <= set(orderables)
    assert {"^penicillin g$", "^amoxicillin$", "^natural latex rubber$"} <= set(allergens)


# TC-UC10-14 (the expansion plan's step 15.1): the common names in db/reference/dictation-names.toml.
def test_each_common_name_stands_for_items_the_reference_data_holds_and_is_an_item_of_its_kind_only():
    entries = tomllib.loads((REPOSITORY / generate_catalog.NAMES).read_text(encoding="utf-8"))["name"]
    orderables, allergens, _ = generate_catalog.names()  # refuses a code the reference data doesn't hold as its kind

    assert {entry["name"] for entry in entries} >= {"penicillin", "latex", "CRP"}
    for entry in entries:
        words = validation._closed_words(entry["name"])
        kind, other = ("order", "allergen") if entry["kind"] == "orderable" else ("allergen", "order")
        assert entry["source"].strip() and entry["codes"]
        assert validation.is_item(words, kind), entry["name"]
        assert not validation.is_item(words, other), entry["name"]
        # A term of art: never a negation, a number word, a stopword, a word of the closed classes or a single letter
        # (the third review's rule), which would make that word an item.
        assert len(words[0]) > 1 and not set(words) & (
            validation.NEVER_IN_AN_ITEM | STOPWORDS | validation._CLOSED_WORDS | validation._NUMBER_WORDS
        ), entry["name"]
    assert "^penicillin$" in allergens and "^latex$" in allergens and "^crp$" in orderables


def test_a_common_name_for_a_code_the_reference_data_does_not_hold_stops_the_generator(tmp_path):
    names = tmp_path / generate_catalog.NAMES
    names.parent.mkdir(parents=True)
    names.write_text('[[name]]\nname = "sulfa"\nkind = "allergen"\ncodes = ["rxnorm:0"]\nsource = "A test."\n')
    wrong_kind = '[[name]]\nname = "latex"\nkind = "orderable"\ncodes = ["unii:2LQ0UUW8IN"]\nsource = "A test."\n'

    with pytest.raises(SystemExit, match="sulfa"):
        generate_catalog.common_names(tmp_path, {"1988-5": "lab"}, {"unii:2LQ0UUW8IN"})
    names.write_text(wrong_kind)
    with pytest.raises(SystemExit, match="latex"):
        generate_catalog.common_names(tmp_path, {"1988-5": "lab"}, {"unii:2LQ0UUW8IN"})
